import type { DialogueEntry } from '../../../../types';
import { CharacterId } from '../../characters';
import { Portrait } from '../../portraits';
import { Background } from '../../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "雨は夕暮れに降りだし、亥の刻になってもやむ気配がなかった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "山の雨は落ちてこない。横ざまに吹きつけてくる。ひとしきり、またひとしきりとすだれを叩くさまは、外で誰かが苛立たしげに本をめくっているようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は赤土の炉の前にしゃがみ、炭をひとつ足した。湯沸かしの水がちょうど泡を立てはじめたところで、細かな粒がひとつ、またひとつと浮かんでくる。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "蟹眼。まだ早い。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は振り向かなかった。帳場の奥に座って、古い急須を磨いている。かれこれ一刻近くになる。急須はとうに、顔が映るほど光っていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）今夜は、何を磨いてもやけに長い。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "湯の音が太くなる。泡がひとまわり大きくなり、浮かんでは弾ける。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "魚眼。急須を温めろ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は湯沸かしを持ち上げ、煮えたぎる湯を急須の肌に回しかけた。湯気が立ちのぼり、顔いっぱいにまとわりつく。紫砂の急須は彼女よりも年上で、蓋には金継ぎの細いひびが一本走っている。眠っている蛇のようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "茶葉を入れ、湯を注ぎ、蓋をして、五つ数える。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一煎目は、捨てる。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "茶は茶盤の下の竹の溝へ流れていった。琥珀色に、少し紅がさしている。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）毎回、もったいないと思う。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "もったいないか。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満はびくりとした。ひと言も口に出していないのに。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "一煎目を捨てるとき、お前はいつも口がへの字になる。七年、ずっとだ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "茶葉は干され、炒られ、揉まれ、焙じられてここまで来る。埃もつく、手の汗もつく、道中の風もつく。一煎目がそれを持っていく。後に続くもののために、誰かが先に苦い思いをせねばならん。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "それじゃ、一煎目ばかり貧乏くじだ。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "うむ。貧乏くじだ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は古い急須を置き、戸口にちらりと目をやった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸の枠には、三本の刻み傷がある。いちばん低いのが小満のもので、横にいびつな「満」の字が彫ってある。上の二本はずっと高く、深く刻まれていた。ひとつは「硯」、もうひとつは「遅」。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）一度だけ、誰のなのか訊いたことがある。その日、師匠はお茶をひと壺、まるごと煮詰めて駄目にした。それきり訊いていない。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸を叩く音。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三度。強くも弱くもなく、力加減を測ったように。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満が閂を外すと、風雨がなだれこんだ。灯火は半分に縮み、また持ちなおした。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸口に、男がひとり立っていた。笠を目深にかぶり、蓑からは水がしたたっている。背中には、油紙で包んだ細長いものを負っていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）剣だ。どれだけ厚く包んでも、あの形は剣だ。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "温伯。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は小満を見なかった。彼女の肩越しに、帳場の奥の老人を見ていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "入れ。床が濡れる。履物を脱げ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は一瞬、動きを止めた。その言葉で何かを思い出したかのように。それから身をかがめて履物を脱ぎ、笠を戸口の脇の釘に掛けた。その釘が何のためにあるのか、小満はずっと知らなかった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）今、わかった。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "笠の下から現れたのは、三十がらみの顔だった。眉骨が高く、唇を固く結んでいる。その線は、鞘に納められた刃のようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "小満、茶を。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は炉のそばに戻り、もう一度急須を温めた。男は窓ぎわの卓につき、油紙の包みを膝の上に横たえた。包みは解かなかった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "あいつは来ましたか。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "まだだ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "来るでしょうか。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "来る。ここはあいつの家だ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "とうに違います。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は何も返さなかった。小満が一煎目を竹の溝へ捨てると、男の視線はその茶の筋をしばらく追い、また戻った。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二煎目は茶海で濃さをならし、男の前の小さな杯に注いだ。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "夜明けに、一線関で。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "知っている。あいつが人に託してよこした手紙は、わしも読んだ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "止めないのですか。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "一度は止めた、お前たちを。止められんものを、二度は止めん。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は杯を手に取ったが、飲まずに、ただ握っていた。湯気が指のあいだを這いのぼっていく。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "十年前のあの晩、私は関で白鷺門の門主の息子と剣を交えました。相手は負けました。私は剣を納め、息の根は止めずにおきました。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "夜が明けると、男はその場で死んでいました。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "阿遅はその夜のうちに出ていきました。私の剣を持ち去り、自分の剣を置いて、戸口にひと言刻んで。――殺したのは俺だ、と。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それを語るあいだ、声には少しの抑揚もなかった。他人の書いた書付を読みあげているようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "理由を訊きに来たのではありません。十年はもう十分に長い。けりをつけに来ただけです。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は茶を飲みほし、杯をそっと卓に戻した。それから顔を上げ、はじめて正面から小満を見た。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "お前は？", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "小満です。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "節気か。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "拾った日が、小満だった。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "……私を拾った日、師匠は墨を磨っていた。阿遅を拾った日は、一歩遅れた。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は戸の枠の二本の刻み傷を、長いあいだ見ていた。それから立ち上がり、二階へ上がっていった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "油紙の包みは、ずっと背負ったままだった。一度も下ろさなかった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）あの人が背負っているのは、別の人の剣だ。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）十年も。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
];
